function renderRestaurantCards(){const p=D.pages.nearby,l=restaurantLabels(),q=restaurantQuery.trim().toLocaleLowerCase(lang);const places=p.places.filter(s=>{const category=restaurantCategory==='all'||(restaurantCategory==='host'?s.host:s.categories.includes(restaurantCategory));const hay=[t(s.name),t(s.category),t(s.text),...t(s.tags)].join(' ').toLocaleLowerCase(lang);return category&&(!q||hay.includes(q))});const list=$('#restaurantCards'),empty=$('#restaurantsEmpty');if(!list)return;const hostPick=$('#restaurantHostPick');if(hostPick){const showHostPick=restaurantCategory==='host';hostPick.hidden=!showHostPick;hostPick.style.display=showHostPick?'':'none'};list.innerHTML=places.map(s=>'<article class="restaurant-card '+(s.host?'is-host':'')+'"><figure class="restaurant-photo"><img src="'+esc(s.image)+'" alt="'+esc(t(s.name))+'" loading="lazy">'+(s.host?'<span class="restaurant-photo-pick"><span class="mi">hotel_class</span> HOST’S PICK</span>':'')+'</figure><div class="restaurant-body"><div class="restaurant-top"><h3 class="restaurant-name">'+esc(t(s.name))+'</h3><span class="restaurant-badge">'+esc(t(s.category))+'</span></div><div class="restaurant-rating"><span class="restaurant-stars"><span class="mi">star</span>Google '+esc(s.rating)+'</span><span>'+esc(s.reviews)+' '+l.reviews+'</span><span>'+esc(t(s.walk))+'</span></div><p class="restaurant-note">'+esc(t(s.text))+'</p><div class="restaurant-tags">'+t(s.tags).map(tag=>'<span>'+esc(tag)+'</span>').join('')+'</div><div class="restaurant-actions"><a class="primary" href="'+esc(s.naver)+'" target="_blank" rel="noopener"><span class="mi">location_on</span>Naver</a><a href="'+esc(s.google)+'" target="_blank" rel="noopener"><span class="mi">map</span>Google</a>'+(s.detailUrl?'<a href="'+esc(s.detailUrl)+'" target="_blank" rel="noopener"><span class="mi">open_in_new</span>'+l.detail+'</a>':'')+'</div></div></article>').join('');empty.style.display=places.length?'none':'block';$('#restaurantCount').textContent=places.length;$('#restaurantCategoryLabel').textContent=t(p.categories.find(c=>c.id===restaurantCategory)?.label||p.categories[1].label)}
function renderRestaurants(){const p=D.pages.nearby,l=restaurantLabels();$('.restaurants-hero .section-kicker').textContent=p.kicker;$('.restaurants-hero h2').textContent=t(p.title);$('.restaurants-hero p:last-child').textContent=t(p.summary);$('.restaurants-hero').style.backgroundImage="linear-gradient(180deg,rgba(35,26,18,.12),rgba(35,26,18,.86)),url('"+p.hero+"')";$('#restaurantsContent').innerHTML='<div class="restaurants-controls"><div class="restaurants-filter" role="tablist" aria-label="Restaurant categories">'+p.categories.map(cat=>'<button class="restaurant-chip '+(cat.id===restaurantCategory?'active':'')+'" type="button" data-restaurant-category="'+cat.id+'">'+esc(t(cat.label))+'</button>').join('')+'</div><label class="restaurant-search"><span class="mi">search</span><input id="restaurantSearch" type="search" value="'+esc(restaurantQuery)+'" placeholder="'+esc(t(p.searchPlaceholder))+'"></label></div><section class="restaurant-host-pick" id="restaurantHostPick"><div class="restaurant-host-pick-head"><span class="restaurant-host-pick-icon"><span class="mi">hotel_class</span></span><div><small>HOST’S PICK</small><strong>'+esc(t(p.hostTitle))+'</strong></div></div></section><div class="restaurant-summary"><b><span id="restaurantCount">0</span> '+l.places+'</b><span id="restaurantCategoryLabel"></span></div><div class="restaurants-list" id="restaurantCards"></div><div class="restaurants-empty" id="restaurantsEmpty">'+esc(l.empty)+'</div>';$$('[data-restaurant-category]').forEach(b=>b.onclick=()=>{restaurantCategory=b.dataset.restaurantCategory;$$('[data-restaurant-category]').forEach(x=>x.classList.toggle('active',x===b));renderRestaurantCards()});$('#restaurantSearch').oninput=e=>{restaurantQuery=e.target.value;renderRestaurantCards()};renderRestaurantCards()}
