function sourceLink(d){const labels=({ko:['사용 설명서 보기','조작 도해 자료 보기'],en:['View user manual','View operation diagram'],ja:['取扱説明書を見る','操作図を見る'],zh:['查看使用说明书','查看操作图']})[lang]||['사용 설명서 보기','조작 도해 자료 보기'];const links=[],manual=t(d.manualUrl),diagram=t(d.guideSourceUrl);if(manual)links.push([manual,labels[0]]);if(diagram)links.push([diagram,labels[1]]);return links.map(x=>'<a class="official-manual-link" href="'+esc(x[0])+'" target="_blank" rel="noopener"><span class="mi">menu_book</span><span>'+esc(x[1])+'</span><span aria-hidden="true">↗</span></a>').join('')}
function guideVisual(d){const localized=t(d.guideImages);const images=(localized||[d.guideImage]).map(t).filter(Boolean);if(!images.length)return '';const label=t(d.name||d.title)||'Operation guide';const figures=images.map((image,i)=>'<figure class="device-guide-visual"><button class="image-zoom" type="button"'+(images.length>1?' data-device-guide-index="'+i+'"':'')+' data-fullscreen-image="'+esc(image)+'" data-fullscreen-title="'+esc(label)+'"><img src="'+esc(image)+'" alt="'+esc(label)+(images.length>1?' '+(i+1):'')+'" loading="lazy"></button>'+(images.length>1?'<span class="device-guide-page" aria-hidden="true">'+String(i+1).padStart(2,'0')+' / '+String(images.length).padStart(2,'0')+'</span>':'')+'</figure>').join('');if(images.length===1)return figures;return '<div class="device-guide-swipe-label" aria-hidden="true"><span>SWIPE</span><span class="mi">swipe</span><span>LEFT / RIGHT</span></div><div class="device-guide-carousel" role="region" aria-label="'+esc(label)+'" tabindex="0">'+figures+'</div>'}
