function applyLightboxTransform(){const image=$('#imageLightboxImg'),lightbox=$('#imageLightbox');if(!image||!lightbox)return;const maxX=Math.max(0,image.clientWidth*(lightboxScale-1)/2),maxY=Math.max(0,image.clientHeight*(lightboxScale-1)/2);lightboxOffsetX=clampLightbox(lightboxOffsetX,-maxX,maxX);lightboxOffsetY=clampLightbox(lightboxOffsetY,-maxY,maxY);image.style.setProperty('--lightbox-scale',lightboxScale.toFixed(3));image.style.setProperty('--lightbox-x',lightboxOffsetX.toFixed(1)+'px');image.style.setProperty('--lightbox-y',lightboxOffsetY.toFixed(1)+'px');lightbox.classList.toggle('is-zoomed',lightboxScale>1.01);}
